/// <reference types="../types/react-table-config" />

import React, { ReactNode, useMemo } from 'react';
import { isElement } from 'react-is';

import { EmptyState } from '../DataTable/EmptyState.js';
import { Pagination } from '../DataTable/Pagination/Pagination.js';
import { DataTableActions } from '../DataTableActions/DataTableActions.js';
import { DataTableSelectedRowsActions } from '../DataTableActions/DataTableSelectedRowsActions.js';
import { DataTableToolbar } from '../DataTableToolbar/DataTableToolbar.js';
import { ExpandableRowTemplate } from '../plugins/use-expandable-row/ExpandableRowTemplate.js';
import { UserActions } from '../plugins/use-user-actions/components/UserActions.js';

export type DataTableSlots = {
  tableActions: ReactNode;
  pagination: ReactNode | null;
  userActions: ReactNode | null;
  toolbar: ReactNode | null;
  selectedRowsActions: ReactNode | null;
  emptyState: ReactNode | null;
  expandableRowTemplate:
    | ((props: { row: Record<string, any> }) => JSX.Element) // eslint-disable-line @typescript-eslint/no-explicit-any
    | null;
};

/** Extracts component slots from DataTable children nodes. */
export function useDataTableSlots(children: ReactNode): DataTableSlots {
  return useMemo(() => {
    const slots: DataTableSlots = {
      pagination: null,
      userActions: null,
      selectedRowsActions: null,
      toolbar: null,
      expandableRowTemplate: null,
      emptyState: null,
      tableActions: null,
    };

    React.Children.forEach(children, (child) => {
      if (isElement(child)) {
        switch (child.type) {
          case Pagination:
            slots.pagination = child;
            break;
          case UserActions:
            slots.userActions = child;
            break;
          case EmptyState:
            slots.emptyState = child;
            break;
          case DataTableToolbar:
            slots.toolbar = child;
            break;
          case DataTableActions:
            slots.tableActions = child;
            break;
          case DataTableSelectedRowsActions:
            slots.selectedRowsActions = child;
            break;
          case ExpandableRowTemplate:
            slots.expandableRowTemplate = child.props.children;
            break;
        }
      }
    });

    return slots;
  }, [children]);
}
